from __future__ import annotations

from typing import Any

from django.db import transaction
from django.http import HttpRequest

from .event_types import USER_SIGNUP
from .tasks import dispatch_webhook_event


def _get_client_ip(request: HttpRequest) -> str:
    x_forwarded_for = request.META.get("HTTP_X_FORWARDED_FOR")
    if x_forwarded_for:
        return x_forwarded_for.split(",")[0].strip()
    return request.META.get("REMOTE_ADDR", "")


def _request_value(request: HttpRequest, key: str) -> str:
    value = request.POST.get(key) or request.GET.get(key)
    if value:
        return str(value)
    if hasattr(request, "session"):
        return str(request.session.get(key, ""))
    return ""


def build_signup_webhook_metadata(
    request: HttpRequest,
    *,
    source: str,
    surface: str,
    auth_method: str,
    provider: str = "",
    client_app: str = "",
    device: dict[str, Any] | None = None,
    invite: dict[str, Any] | None = None,
    extra_signup: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Build request-time metadata for signup webhooks."""
    request_data = {
        "ip_address": _get_client_ip(request),
        "user_agent": request.META.get("HTTP_USER_AGENT", "")[:500],
        "referrer": request.META.get("HTTP_REFERER", "")[:500],
        "path": request.path,
    }
    acquisition = {
        "utm_source": _request_value(request, "utm_source")[:100],
        "utm_medium": _request_value(request, "utm_medium")[:100],
        "utm_campaign": _request_value(request, "utm_campaign")[:100],
        "utm_content": _request_value(request, "utm_content")[:100],
        "utm_term": _request_value(request, "utm_term")[:100],
    }
    resolved_client_app = client_app or getattr(request, "client_app", "")
    signup_data: dict[str, Any] = {
        "source": source,
        "surface": surface,
        "auth_method": auth_method,
    }
    if provider:
        signup_data["provider"] = provider
    if resolved_client_app:
        signup_data["client_app"] = resolved_client_app
    if extra_signup:
        signup_data.update(extra_signup)

    metadata: dict[str, Any] = {
        "signup": signup_data,
        "request": request_data,
        "acquisition": acquisition,
    }
    if device:
        metadata["device"] = device
    if invite:
        metadata["invite"] = invite
    return metadata


def queue_user_signup_webhook(
    user_id: str,
    metadata: dict[str, Any] | None = None,
) -> None:
    """Queue a user signup webhook after the current transaction commits."""

    def _queue() -> None:
        dispatch_webhook_event.delay(
            event_type=USER_SIGNUP,
            payload_arg=user_id,
            idempotency_suffix=user_id,
            payload_metadata=metadata,
        )

    transaction.on_commit(_queue)

"""
Payload builders for webhook events.

Each function builds a standardized payload for a specific event type.
"""

from __future__ import annotations

import logging
from copy import deepcopy
from datetime import datetime
from typing import Any

from django.contrib.auth.models import User
from django.utils import timezone

from users.models import FamilyMembership

from .event_types import USER_SIGNUP

logger = logging.getLogger(__name__)

# API version for payload format
PAYLOAD_API_VERSION = "1.0"


def build_base_payload(event_type: str, data: dict[str, Any]) -> dict[str, Any]:
    """
    Build the base webhook payload structure.

    All webhooks share this common format.
    """
    return {
        "event_type": event_type,
        "timestamp": timezone.now().isoformat(),
        "api_version": PAYLOAD_API_VERSION,
        "data": data,
    }


def _merge_metadata(
    base: dict[str, Any],
    metadata: dict[str, Any] | None,
) -> dict[str, Any]:
    """Merge shallow nested signup metadata without mutating caller input."""
    merged = deepcopy(base)
    if not metadata:
        return merged

    for key, value in metadata.items():
        if isinstance(value, dict) and isinstance(merged.get(key), dict):
            merged[key].update(value)
        else:
            merged[key] = value
    return merged


def _compact_dict(data: dict[str, Any]) -> dict[str, Any]:
    return {key: value for key, value in data.items() if value not in ("", None, {})}


def _latest_mobile_device_data(user: User) -> dict[str, Any]:
    try:
        from mobile.models import MobileDevice

        device = MobileDevice.objects.filter(user=user).first()
        if not device:
            return {}
        return _compact_dict(
            {
                "id": str(device.id),
                "device_id": device.device_id,
                "type": device.device_type,
                "name": device.device_name,
                "client_app": device.client_app,
                "has_push_token": bool(device.push_token),
                "last_login": device.last_login.isoformat()
                if device.last_login
                else None,
            }
        )
    except Exception as e:
        logger.warning("Could not fetch mobile device for user %s: %s", user.id, e)
        return {}


def _profile_acquisition_data(user: User) -> dict[str, Any]:
    acquisition: dict[str, Any] = {}
    try:
        profile = user.profile
        if profile.discovery_source:
            acquisition["discovery_source"] = profile.discovery_source
        if profile.discovery_region_id:
            acquisition["discovery_region"] = {
                "id": str(profile.discovery_region_id),
                "name": profile.discovery_region.name,
                "slug": profile.discovery_region.slug,
            }
    except Exception as e:
        logger.warning(
            "Could not fetch profile acquisition for user %s: %s", user.id, e
        )

    try:
        from users.models import ConversionTracking

        conversion = (
            ConversionTracking.objects.filter(user=user).order_by("-created_at").first()
        )
        if conversion:
            acquisition.update(
                _compact_dict(
                    {
                        "utm_source": conversion.utm_source,
                        "utm_medium": conversion.utm_medium,
                        "utm_campaign": conversion.utm_campaign,
                        "utm_content": conversion.utm_content,
                        "utm_term": conversion.utm_term,
                        "referrer": conversion.referrer,
                        "user_agent": conversion.user_agent,
                        "ip_address": str(conversion.ip_address)
                        if conversion.ip_address
                        else "",
                        "conversion_stage": conversion.stage,
                        "conversion_metadata": conversion.metadata,
                    }
                )
            )
    except Exception as e:
        logger.warning("Could not fetch conversion data for user %s: %s", user.id, e)

    return acquisition


def build_user_signup_payload(
    user_id: str,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """
    Build the payload for a user signup event.

    Args:
        user_id: UUID of the newly signed up user (as string)

    Returns:
        Complete webhook payload dictionary
    """
    try:
        user = User.objects.get(id=user_id)
    except User.DoesNotExist:
        logger.error(f"Cannot build user signup payload: User {user_id} not found")
        return build_base_payload(
            USER_SIGNUP,
            {"error": "User not found", "user_id": user_id},
        )

    # Build user data
    user_data: dict[str, str | datetime | None] = {
        "id": str(user.id),
        "email": user.email,
        "first_name": user.first_name,
        "last_name": user.last_name,
        "username": user.username,
        "date_joined": user.date_joined.isoformat() if user.date_joined else None,
    }

    # Get family membership info if available
    family_data: dict[str, str | None] | None = None
    try:
        membership = FamilyMembership.objects.filter(user=user).first()
        if membership:
            family_data = {
                "id": str(membership.family.id),
                "name": membership.family.name,
                "role": membership.role,
            }
    except Exception as e:
        logger.warning(f"Could not fetch family membership for user {user_id}: {e}")

    # Determine signup method
    # Check if user has any social accounts
    signup_method = "standard"
    provider_name = ""
    try:
        from allauth.socialaccount.models import SocialAccount

        social_accounts = SocialAccount.objects.filter(user=user)
        if social_accounts.exists():
            provider = social_accounts.first()
            if provider:
                provider_name = provider.provider
                signup_method = f"social:{provider.provider}"
    except ImportError:
        pass  # allauth not installed
    except Exception as e:
        logger.warning(f"Could not determine signup method for user {user_id}: {e}")

    signup_data = {
        "method": signup_method,
        "auth_method": "social" if signup_method.startswith("social:") else "email",
    }
    if provider_name:
        signup_data["provider"] = provider_name

    request_metadata = metadata or {}
    request_signup = request_metadata.get("signup")
    if isinstance(request_signup, dict):
        auth_method = request_signup.get("auth_method")
        provider = request_signup.get("provider")
        if auth_method == "social" and provider:
            signup_method = f"social:{provider}"
            signup_data["method"] = signup_method
            signup_data["provider"] = provider
            signup_data["auth_method"] = "social"
        elif auth_method == "email":
            signup_method = "standard"
            signup_data["method"] = signup_method
            signup_data["auth_method"] = "email"

    base_metadata: dict[str, Any] = {
        "signup": signup_data,
        "device": _latest_mobile_device_data(user),
        "acquisition": _profile_acquisition_data(user),
    }
    merged_metadata = _merge_metadata(base_metadata, metadata)

    data: dict[str, Any] = {
        "user": user_data,
        "signup_method": signup_method,
    }

    if family_data:
        data["family"] = family_data

    for key in ("signup", "device", "request", "acquisition", "invite"):
        value = merged_metadata.get(key)
        if isinstance(value, dict):
            value = _compact_dict(value)
        if value:
            data[key] = value

    return build_base_payload(USER_SIGNUP, data)

